@startuml

class Gym {
  + ComputeMonthlyBalance(month: int, year: int): double
  + ComputeAnnualBalance(year: int): double
  + SendArrearsReminder(): void
  + SendCheckReminder(): void
}

class Customer {
  + Name : string
  + Surname : string
  + Age : int
  + Address : string
  + Profession : string
}

class Subscription {
  + Type : string
}

class AdditionalService {
  + Name : string
}

class WorkoutPlan {
  + Exercises : string
  + Repetitions : int
  + Frequency : int
}

class MedicalCheck {
  + Date : date
  + Weight : float
  + BodyFat : float
  + Electrocardiogram : string
  + RestingHeartbeat : int
  + StressHeartbeat : int
}

class MedicalStaff {
  + Name : string
}

class Diet {
  + Description : string
}

class FitnessLevel {
  + Level : string
}

Gym "1" -- "*" Customer : manages
Gym "1" -- "*" Subscription : offers
Gym "1" -- "*" AdditionalService : offers
Gym "1" -- "*" MedicalStaff : employs

Customer "1" -- "1" Subscription : has
Customer "0..1" -- "0..1" WorkoutPlan : follows
Customer "0..1" -- "*" AdditionalService : requests
Customer "0..1" -- "*" MedicalCheck : undergoes
Customer "0..1" -- "0..1" Diet : follows
Customer "0..1" -- "0..1" FitnessLevel : has

MedicalStaff "1" -- "*" MedicalCheck : performs
MedicalStaff "1" -- "1" Diet : defines
MedicalStaff "1" -- "1" FitnessLevel : determines

@enduml

